{
  "story": "Packets flow down through the seven layers of the OSI model during transmission and back up during reception. Each layer adds or removes specific encapsulation.",
  "aha": {
    "stateId": "transport",
    "observation": "Layer 4 divides data into segments, establishing reliable end-to-end communication before routing."
  },
  "layout": {
    "preset": "stepper-vertical",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.step",
        "items": "variant.states"
      }
    },
    {
      "id": "pic",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.step",
        "regions": "variant.regions",
        "values": "state.readouts"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.step"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "label": "OSI Layer",
      "options": ["Application", "Presentation", "Session", "Transport", "Network", "Data Link", "Physical"]
    },
    {
      "id": "res",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "OSI 7 Layers",
        "regions": [
          {"id": "app", "label": "Layer 7: Application", "kind": "layer", "values": ["HTTP", "FTP", "DNS"]},
          {"id": "pres", "label": "Layer 6: Presentation", "kind": "layer", "values": ["SSL", "TLS", "JPEG"]},
          {"id": "sess", "label": "Layer 5: Session", "kind": "layer", "values": ["NetBIOS", "RPC"]},
          {"id": "trans", "label": "Layer 4: Transport", "kind": "layer", "values": ["TCP", "UDP"]},
          {"id": "net", "label": "Layer 3: Network", "kind": "layer", "values": ["IP", "ICMP", "Routers"]},
          {"id": "data", "label": "Layer 2: Data Link", "kind": "layer", "values": ["Ethernet", "MAC", "Switches"]},
          {"id": "phys", "label": "Layer 1: Physical", "kind": "layer", "values": ["Cables", "Hubs", "Bits"]}
        ],
        "states": [
          {
            "id": "application",
            "label": "7. Application",
            "short": "App",
            "sentence": "The application layer interfaces directly with software applications.",
            "why": "Provides network services to user applications.",
            "active": ["app"],
            "calloutRegion": "app",
            "readouts": [{"id": "r1", "label": "PDU", "value": "Data"}, {"id": "r2", "label": "Device", "value": "Host"}]
          },
          {
            "id": "presentation",
            "label": "6. Presentation",
            "short": "Pres",
            "sentence": "Data is translated, encrypted, and compressed here.",
            "why": "Ensures data is in a readable format for the application layer.",
            "active": ["pres"],
            "calloutRegion": "pres",
            "readouts": [{"id": "r1", "label": "PDU", "value": "Data"}, {"id": "r2", "label": "Action", "value": "Translate"}]
          },
          {
            "id": "session",
            "label": "5. Session",
            "short": "Sess",
            "sentence": "Manages communication sessions and dialogs between hosts.",
            "why": "Controls opening, closing, and establishing connections.",
            "active": ["sess"],
            "calloutRegion": "sess",
            "readouts": [{"id": "r1", "label": "PDU", "value": "Data"}, {"id": "r2", "label": "Action", "value": "Dialog"}]
          },
          {
            "id": "transport",
            "label": "4. Transport",
            "short": "Trans",
            "sentence": "Segments data and guarantees reliable delivery using TCP or UDP.",
            "why": "Handles error checking and flow control end-to-end.",
            "active": ["trans"],
            "calloutRegion": "trans",
            "readouts": [{"id": "r1", "label": "PDU", "value": "Segment"}, {"id": "r2", "label": "Protocol", "value": "TCP/UDP"}]
          },
          {
            "id": "network",
            "label": "3. Network",
            "short": "Net",
            "sentence": "Adds logical IP addresses and handles packet routing.",
            "why": "Determines the best path across interconnected networks.",
            "active": ["net"],
            "calloutRegion": "net",
            "readouts": [{"id": "r1", "label": "PDU", "value": "Packet"}, {"id": "r2", "label": "Addressing", "value": "IP"}]
          },
          {
            "id": "datalink",
            "label": "2. Data Link",
            "short": "Data",
            "sentence": "Frames packets and uses MAC addresses for node-to-node delivery.",
            "why": "Manages physical media access and error detection on the local link.",
            "active": ["data"],
            "calloutRegion": "data",
            "readouts": [{"id": "r1", "label": "PDU", "value": "Frame"}, {"id": "r2", "label": "Addressing", "value": "MAC"}]
          },
          {
            "id": "physical",
            "label": "1. Physical",
            "short": "Phys",
            "sentence": "Transmits raw binary bits over physical network media.",
            "why": "Converts frames into electrical, optical, or radio signals.",
            "active": ["phys"],
            "calloutRegion": "phys",
            "readouts": [{"id": "r1", "label": "PDU", "value": "Bits"}, {"id": "r2", "label": "Media", "value": "Cable/Radio"}]
          }
        ]
      }
    ]
  }
}
